use super::*;

/// Post a turn into a loop AND deliver it to the other participant.
///
/// # Why this is a `bsc session` verb and not `bsc loop say`
///
/// Making `say` deliver would need `bsc-loop` to resolve a participant to a session and reach the app —
/// that is `bsc-loop -> bsc-session`, while `ask` opening a loop is `bsc-session -> bsc-loop`. A
/// dependency CYCLE. Keeping both verbs here holds one direction and leaves `bsc loop` a generic
/// conversation store that knows nothing about system sessions, so the designer pump is untouched.
///
/// # The loop still bounds the exchange
///
/// The store refuses a turn that is not this participant's, or one into a closed loop, and it closes on
/// the signal or the ceiling. None of that moved: this adds a push to a turn that was already posted.
pub fn reply(
    env: &dyn ReplyEnv,
    loop_id: i64,
    text: &str,
    speaker: &str,
) -> Result<ReplyResult, String> {
    let text = text.trim();
    if text.is_empty() {
        return Err(format!("usage: bsc session reply {loop_id} \"<your answer>\""));
    }
    let (a, b) = env.participants(loop_id)?;
    // WHO IS THE OTHER SIDE. Resolved before the write so a reply naming a loop this speaker is not in
    // fails without posting a turn nobody can receive.
    let other = if speaker == a {
        b
    } else if speaker == b {
        a
    } else {
        return Err(format!(
            "'{speaker}' is not a participant in loop {loop_id} (its two are '{a}' and '{b}') — a turn \
             from outside the exchange has nobody to reach."
        ));
    };

    let posted = env.say(loop_id, speaker, text)?;

    // DELIVER it onward. A participant that is not a system session is a reported no-op — see
    // `ReplyResult::delivered_to`.
    let (delivered_to, delivery) = match crate::resolve(&other) {
        Ok(target) => {
            let carried = reply_prompt(loop_id, &target.id, speaker, text, posted.closed.as_deref());
            let action = env.deliver(&target.id, &carried)?;
            (Some(target.id.to_string()), Some(action))
        }
        Err(_) => (None, None),
    };
    Ok(ReplyResult { loop_id, seq: posted.seq, closed: posted.closed, delivered_to, delivery })
}
